uniform vec3 uColor; uniform vec3 uLight:
uniform vec3 uColor; uniform vec3 uLight; uniform float uSeed; uniform float uShine;
varying vec3 vN; varying vec3 vW; varying vec3 vP;
float hash(vec3 p) { return fract(sin(dot(p, vec3(12.9898, 78.233, 37.719))) * 43758.5453); }
float noise(vec3 p) {
  vec3 i = floor(p); vec3 f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(hash(i), hash(i + vec3(1,0,0)), f.x), mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),
             mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x), mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y), f.z);
}
void main() {
  vec3 n = normalize(vN);
  vec3 L = normalize(uLight);
  // Folds: big vertically stretched strokes; grain: canvas texture. Uses the part's own coordinates so the pattern moves with the body when walking
  float folds = noise(vP * vec3(26.0, 7.0, 26.0) + uSeed);
  float grain = noise(vP * vec3(90.0, 150.0, 90.0) - uSeed);
  // Wrap lighting: shadows never go pitch black; soft transition but strong contrast
  float l = clamp((dot(n, L) + 0.35) / 1.35, 0.0, 1.0);
  l = smoothstep(0.12, 0.88, l + (folds - 0.5) * 0.38);
  vec3 c = uColor * mix(vec3(0.33, 0.37, 0.50), vec3(1.14, 1.03, 0.88), l);   // cool shadows -> warm highlights
  // Hand-painted highlights (brighter on leather and hair), broken up along the folds
  vec3 h = normalize(L + vec3(0.0, 0.0, 1.0));
  c += pow(max(dot(n, h), 0.0), 16.0) * uShine * (0.4 + folds) * 0.4;
  // Lower body slightly darker (near the ground, less light)
  c *= 0.76 + 0.24 * smoothstep(0.0, 1.5, vW.y);
  c *= 0.93 + 0.14 * grain;
  // Sky-light rim (cool, very faint)
  c += vec3(0.30, 0.40, 0.55) * pow(1.0 - abs(n.z), 4.0) * 0.16;
  gl_FragColor = vec4(c, 1.0);
}

uniform sampler2D uMap; uniform vec3 uLi:
uniform sampler2D uMap; uniform vec3 uLight; uniform vec3 uCloth; uniform float uClothAmt;
varying vec2 vUv; varying vec3 vN; varying vec3 vW;
void main() {
  vec3 base = texture2D(uMap, vUv).rgb;
  float lum = dot(base, vec3(0.299, 0.587, 0.114));
  // Warm colors (skin, leather, hair, red scarf): R > G > B. These keep their original color: not recolored with the clothes, not cooled
  float warm = clamp((base.r - base.b - 0.03) * 9.0, 0.0, 1.0) * clamp((base.r - base.g) * 14.0 + 0.6, 0.0, 1.0);
  // Each person's clothing color: cool and gray fabric (coats, trousers, shirts) is dyed this person's color by brightness, so everyone is easy to tell apart
  float cl = dot(uCloth, vec3(0.299, 0.587, 0.114));
  vec3 dyed = uCloth * (lum / max(0.08, cl));
  base = mix(base, clamp(dyed, 0.0, 1.0), uClothAmt * (1.0 - warm) * smoothstep(0.03, 0.12, lum));
  vec3 n = normalize(vN);
  float l = clamp((dot(n, uLight) + 0.5) / 1.5, 0.0, 1.0);
  l = smoothstep(0.1, 0.9, l);
  // The texture already has painted shading, so only add a light layer: slightly cool shadows, warm highlights (shadows used to be too blue, making faces look like zombies)
  vec3 c = base * mix(vec3(0.88, 0.87, 0.92), vec3(1.16, 1.09, 1.0), l);
  // Skin a bit warmer and more saturated: healthy color
  vec3 g = vec3(dot(c, vec3(0.299, 0.587, 0.114)));
  c = mix(c, mix(g, c, 1.35) * vec3(1.06, 0.99, 0.93), warm * 0.8);
  c *= 0.92 + 0.08 * smoothstep(0.0, 1.4, vW.y);   // Lower body slightly darker
  gl_FragColor = vec4(c, 1.0);
}
